1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Customer {
14	  yearsWithMHPCO: number;
15	}
16	
17	export interface Scenario {
18	  customer: Customer;
19	  steps: QuoteStep[];
20	}
21	
22	export interface ScenarioResults {
23	  results: unknown[];
24	}
