26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const CURSE_SURCHARGE = 0.5;
29	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
30	const HIGH_ENCHANTMENT_THRESHOLD = 5;
31	const LOYALTY_DISCOUNT = 0.2;
32	const LOYALTY_THRESHOLD_YEARS = 2;
33	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
34	
35	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
36	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
37	
38	const BASE_PREMIUMS: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	  potion: 40,
43	  rune: 25,
44	  moonstone: 25,
45	};
46	
47	const COMPONENT_TYPES = ["rune", "moonstone"];
48	const BLOCK_SIZE = 3;
49	const BLOCK_BASE_PREMIUM = 60;
50	
51	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
52	
53	const countByType = (items: Item[]): Map<string, number> => {
54	  const counts = new Map<string, number>();
55	
56	  for (const item of items) {
57	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
58	  }
59	
60	  return counts;
61	};
62	
63	/** Exactly BLOCK_SIZE alike components form a building block. */
64	const formsBuildingBlock = (type: string, count: number): boolean =>
65	  isComponent(type) && count === BLOCK_SIZE;
66	
67	const itemBasePremium = (type: string): number => BASE_PREMIUMS[type];
68	
69	/** Alike items are priced together so a building block can be recognised. */
70	const groupBasePremium = (type: string, count: number): number =>
71	  formsBuildingBlock(type, count)
72	    ? BLOCK_BASE_PREMIUM
73	    : count * itemBasePremium(type);
74	
75	/** The policy base premium is the sum of the base premiums of its items. */
76	const policyBasePremium = (items: Item[]): number =>
77	  [...countByType(items)].reduce(
78	    (total, [type, count]) => total + groupBasePremium(type, count),
79	    0,
80	  );
81	
82	const isCursed = (item: Item): boolean => item.cursed === true;
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	/**
88	 * Item-specific surcharges stack additively, as fractions of the item's base
89	 * premium.
90	 */
91	const itemSurchargeRate = (item: Item): number =>
92	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
93	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
94	
95	/**
96	 * Item-specific modifiers apply to the base premium of the affected item,
97	 * not to the policy total.
98	 */
99	const itemSurcharges = (items: Item[]): number =>
100	  items.reduce(
101	    (total, item) =>
102	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
103	    0,
104	  );
105	
106	const isLoyalCustomer = (customer: Customer): boolean =>
107	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
108	
109	/**
110	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
111	 * amount added to (or, when negative, subtracted from) that base premium, so
112	 * modifiers stack additively rather than compounding.
113	 */
114	const policyModifierRates = (
115	  customer: Customer,
116	  previousContracts: number,
117	): number[] => [
118	  FIRST_INSURANCE_SURCHARGE,
119	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
120	  previousContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
121	];
122	
123	const policyModifiers = (
124	  basePremium: number,
125	  customer: Customer,
126	  previousContracts: number,
127	): number =>
128	  policyModifierRates(customer, previousContracts).reduce(
129	    (total, rate) => total + basePremium * rate,
130	    0,
131	  );
132	
133	const quotePremium = (
134	  step: QuoteStep,
135	  customer: Customer,
136	  previousContracts: number,
137	): number => {
138	  const basePremium = policyBasePremium(step.items);
139	
140	  return roundUp(
141	    basePremium +
142	      itemSurcharges(step.items) +
143	      policyModifiers(basePremium, customer, previousContracts) +
144	      PROCESSING_FEE,
145	  );
146	};
147	
148	export const runScenario = (scenario: Scenario): ScenarioResults => ({
149	  results: scenario.steps.map((step, index) => ({
150	    premium: quotePremium(step, scenario.customer, index),
151	  })),
152	});
