const policyModifierRates = (
  customer: Customer,
  previousContracts: number,
): number[] => [
  FIRST_INSURANCE_SURCHARGE,
  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
  previousContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
];

const policyModifiers = (
  basePremium: number,
  customer: Customer,
  previousContracts: number,
): number =>
  policyModifierRates(customer, previousContracts).reduce(
    (total, rate) => total + basePremium * rate,
    0,
  );

const quotePremium = (
  step: QuoteStep,
  customer: Customer,
  previousContracts: number,
): number => {
  const basePremium = policyBasePremium(step.items);

  return roundUp(
    basePremium +
      itemSurcharges(step.items) +
      policyModifiers(basePremium, customer, previousContracts) +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, index) => ({
    premium: quotePremium(step, scenario.customer, index),
  })),
});

